INSERT INTO "activities" VALUES(41,'Krao Cave — Conquest Hard','Expedition','Krao Cave','Conquest Hard','1★',1,1,1,'per_character','opportunity',NULL,0.0,NULL,NULL,1.0,1.0,NULL,12.0,40.0,0.0,0.0,0.0,2400.0,2600.0,0,'none',0.0,NULL,NULL,1,'global_lst','provisional',21.02,'Global client reward line per claim (40 Odyle; 2 claims with membership). KR (Jul 2026): 510k bound per claim. Kinah falloff per server-week (KR): Exploration 100% up to 7 claims, 60% to 14, 20% to 20, 0% from 21; Conquest 100% up to 63 (pre-S3 84), then 80/60/40/20%. Leaving without claiming uses a weekly unclaimed-cube allowance (~10, shared per server). Global launch: 6 dungeons, 5-player parties. Minutes estimated. https://dbaion2.ru/en/dungeons/ ; https://game8.co/games/Aion-2/archives/613829 ; https://aion2.wiki.fextralife.com/Expeditions ; https://www.inven.co.kr/board/aion2/6444/2064',NULL,NULL,NULL,NULL,NULL,NULL);
