INSERT INTO "progression_items" VALUES(1,'skills','own','Skill points from leveling (1→45)','',45,1.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',0,'About 230–258 skill points by 45 depending on class (enough for ~11–12 skills at Lv10). Skill Lv8 = 13 pts, Lv10 = 21 pts; Lv8/12/16 unlock specialization slots. Skill levels do NOT add Item Level (GS); they add Combat Power. Levels above 10 come from Daevanion nodes, gear and Arcana. https://mmo-codex.com/articles/aion-2-sorcerer-guide/',NULL);
INSERT INTO "progression_items" VALUES(2,'skills','own','Stigma slots (unlock at level 23)','',23,4.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',1,'4 Stigma slots. Levelled only with Stigma Shards (Abyss/PvP shops, Ascension Trial, Shugo Festa). CP per stigma level: 1→5 ≈0.9K, 5→10 ≈2K, 10→15 ≈3.5K, 15→20 ≈6K. https://vortexgaming.io/en/postdetail/717212',NULL);
INSERT INTO "progression_items" VALUES(3,'daevanion','own','Nezekan board','',12,1.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',2,'Full board: +1 level to 11 skills, HP +1,000, Attack Bonus +180, Defense Bonus +1,400. Point total not found. Node costs: stat 1, passive 2, active 3, unique 4. +1 Item Level per point spent. https://aion2.wiki.fextralife.com/Daevanion_Boards ; https://gamerstogether.cz/en/aion-2-daevanion/',NULL);
INSERT INTO "progression_items" VALUES(4,'daevanion','own','Zikel board','',20,1.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',3,'59 points (TW). +1 Item Level per point spent. https://aion2.wiki.fextralife.com/Daevanion_Boards ; https://gamerstogether.cz/en/aion-2-daevanion/',59.0);
INSERT INTO "progression_items" VALUES(5,'daevanion','own','Vaizel board','',30,1.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',4,'70 points (TW). +1 Item Level per point spent. https://aion2.wiki.fextralife.com/Daevanion_Boards ; https://gamerstogether.cz/en/aion-2-daevanion/',70.0);
INSERT INTO "progression_items" VALUES(6,'daevanion','own','Triniel board','',40,1.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',5,'Point total not found. https://aion2.wiki.fextralife.com/Daevanion_Boards ; https://gamerstogether.cz/en/aion-2-daevanion/',NULL);
INSERT INTO "progression_items" VALUES(7,'daevanion','own','Ariel board (PvE)','',45,1.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',6,'128 points (TW). Ariel crystals from duty/mission quests and Nightmare. https://aion2.wiki.fextralife.com/Daevanion_Boards ; https://gamerstogether.cz/en/aion-2-daevanion/',128.0);
INSERT INTO "progression_items" VALUES(8,'daevanion','own','Azphel board (PvP)','',45,1.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',7,'128 points (TW). Azphel crystals from Abyss shop, Proving Ground, Ereshkigal Monolith. https://aion2.wiki.fextralife.com/Daevanion_Boards ; https://gamerstogether.cz/en/aion-2-daevanion/',128.0);
INSERT INTO "progression_items" VALUES(9,'daevanion','own','Level-up Daevanion points','',45,1.0,0.0,'per_character',1,1,1,'kr_tw_reference','unknown',8,'Level-up rewards give Daevanion points (amount not found). Almost 400 points total are available by 45 (global guide) including quests/sealed dungeons. https://mmo-codex.com/articles/aion-2-leveling-guide/',NULL);
INSERT INTO "progression_items" VALUES(10,'daevanion','own','Shugo Festa shop crystals','',45,1.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',9,'15 per character on TW (7 on KR). https://aion2.wiki.fextralife.com/Daevanion_Boards ; https://gamerstogether.cz/en/aion-2-daevanion/',NULL);
INSERT INTO "progression_items" VALUES(11,'daevanion','own','Nightmare shop crystals','',45,1.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',10,'15 per character. https://aion2.wiki.fextralife.com/Daevanion_Boards ; https://gamerstogether.cz/en/aion-2-daevanion/',NULL);
INSERT INTO "progression_items" VALUES(12,'daevanion','own','Substance Morph crystal','',45,1.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',11,'1 crystal = 100 fragments + 50 Odyle (repeatable; count = how many you plan). https://aion2.wiki.fextralife.com/Daevanion_Boards ; https://gamerstogether.cz/en/aion-2-daevanion/',NULL);
INSERT INTO "progression_items" VALUES(13,'side_quests','own','Regional quests (Verteron / Altgard)','Verteron / Altgard',10,73.0,5.0,'per_character',1,1,1,'kr_tw_reference','provisional',12,'73 per faction map (game8). Rewards per quest: EXP 0.01–2%, 10k–100k bound Kinah (avg used: 50k), usually 2–3 Daevanion crystals (avg used: 2.5). Minutes per quest is an estimate. https://game8.co/games/Aion-2/archives/623928',NULL);
INSERT INTO "progression_items" VALUES(14,'side_quests','own','Regional quests (Abyss)','Abyss',45,0.0,5.0,'per_character',1,1,1,'kr_tw_reference','unknown',13,'Count not found. https://game8.co/games/Aion-2/archives/623928',NULL);
INSERT INTO "progression_items" VALUES(15,'side_quests','enemy','Rift quests (enemy territory)','Enemy map via Rift',45,7.0,5.0,'per_character',1,1,1,'kr_tw_reference','provisional',14,'7 Rift quests per entrance (7mmo). Reward Daevanion and Abyss Points (amounts not found). Rifts open every 3–4 h for 1 h on KR; disabled in the Global LST. https://www.inven.co.kr/board/aion2/6444/305 ; https://www.gavara.org/forums/topic/aion-2-rift-rewards-guide-better-runs-with-u4n-strategies',NULL);
INSERT INTO "progression_items" VALUES(16,'strongholds','own','Strongholds (garrisons)','Verteron / Altgard',10,15.0,10.0,'per_character',1,1,1,'kr_tw_reference','provisional',15,'14–15 per faction map (sources disagree). One-time chest: 15,000 Kinah + 2 Noble Belt Enhance Scrolls (only source of belt scrolls) + some titles. Daevanion: 2 per gamerstogether, none per game8/aion2hub (not counted). Minutes is an estimate; Stronghold Express Vouchers auto-clear a region. https://www.gametoc.co.kr/news/articleView.html?idxno=104144 ; https://game8.co/games/Aion-2/archives/617436',NULL);
INSERT INTO "progression_items" VALUES(17,'strongholds','enemy','Enemy strongholds (via Rift)','Enemy map via Rift',45,15.0,10.0,'per_character',1,1,1,'kr_tw_reference','provisional',16,'Needed to get enough belt scrolls for a Unique Noble Belt. Same chest assumed. https://www.gametoc.co.kr/news/articleView.html?idxno=104144 ; https://game8.co/games/Aion-2/archives/617436',NULL);
INSERT INTO "progression_items" VALUES(18,'hidden_dungeons','own','Sealed dungeons','Verteron / Altgard',15,61.0,10.0,'per_character',1,1,1,'kr_tw_reference','provisional',17,'61 per faction map (game8; aion2hub lists 55 by tier). First clear: 15k Kinah, 2 Daevanion crystals, 2 Wisdom Stones (skill points), 1.2–1.25k Enhancement Stones, 2 Sealed Wing Featherdown, 2 Pantheon statue scraps. ''Ruins of the Ancient City of Ru'' gives 20/20 wing materials. ≤10 min each. https://game8.co/games/Aion-2/archives/617999 ; https://aion2hub.com/leveling/elyos-levels-10-25',NULL);
INSERT INTO "progression_items" VALUES(19,'hidden_dungeons','enemy','Enemy sealed dungeons (via Rift)','Enemy map via Rift',45,61.0,10.0,'per_character',1,1,1,'kr_tw_reference','provisional',18,'500 Abyss Points each and ''a significant amount of Daevanion'' (amount not found). https://www.inven.co.kr/board/aion2/6444/305 ; https://www.gavara.org/forums/topic/aion-2-rift-rewards-guide-better-runs-with-u4n-strategies',NULL);
INSERT INTO "progression_items" VALUES(20,'feathers','own','Monolith Verteron / Altgard (30 levels)','Verteron / Altgard',10,1.0,0.0,'per_server',1,1,0,'kr_tw_reference','provisional',19,'560 traces to Lv30; since KR 2025-12-03 each feather gives 4 traces. Shared per server since KR 2025-12-17 (expected on Global). Cumulative: 112 Wisdom Stones, Action Power +320, 30 Revelation Amulet scrolls (only source), 11 Hidden Cube keys, 20 Soul Codex resets, stats, 2 outfits, titles at Lv10/20/30. Extra traces → 50 Enhancement Stones each (max 1,680/server). Hours not found. https://game8.co/games/Aion-2/archives/617446',NULL);
INSERT INTO "progression_items" VALUES(21,'feathers','own','Monolith Ereshkigal (Abyss)','Abyss',45,1.0,0.0,'per_server',1,1,0,'kr_tw_reference','unknown',20,'PvP stats and Azphel crystals; 20 levels (title at 20). Details not found. https://game8.co/games/Aion-2/archives/617446',NULL);
INSERT INTO "progression_items" VALUES(22,'feathers','enemy','Enemy Empyrean traces (via Rift)','Enemy map via Rift',45,1.0,0.0,'per_server',1,1,0,'kr_tw_reference','unknown',21,'Traces are faction-specific; enemy traces can be collected during Rifts. Reward track not found. https://game8.co/games/Aion-2/archives/617446',NULL);
INSERT INTO "progression_items" VALUES(23,'genus','own','Genus: Intellect (Cogni)','',1,41.0,0.0,'per_server',1,1,0,'kr_tw_reference','provisional',22,'41 pets. Kill a monster type to collect Pet Souls; each pet to understanding Lv5 needs 500 souls (sagye) or 1,010 (gameple). Pets/souls shared per server. Stats: HP, Crit, Power, Knowledge, dmg vs genus. https://sagye.kr/tips/pets ; https://www.gametoc.co.kr/news/articleView.html?idxno=105439',NULL);
INSERT INTO "progression_items" VALUES(24,'genus','own','Genus: Wild (Fera)','',1,65.0,0.0,'per_server',1,1,0,'kr_tw_reference','provisional',23,'65 pets. https://sagye.kr/tips/pets ; https://www.gametoc.co.kr/news/articleView.html?idxno=105439',NULL);
INSERT INTO "progression_items" VALUES(25,'genus','own','Genus: Natura','',1,48.0,0.0,'per_server',1,1,0,'kr_tw_reference','provisional',24,'48 pets. https://sagye.kr/tips/pets ; https://www.gametoc.co.kr/news/articleView.html?idxno=105439',NULL);
INSERT INTO "progression_items" VALUES(26,'genus','own','Genus: Transformation (Varian)','',1,46.0,0.0,'per_server',1,1,0,'kr_tw_reference','provisional',25,'46 pets. https://sagye.kr/tips/pets ; https://www.gametoc.co.kr/news/articleView.html?idxno=105439',NULL);
INSERT INTO "progression_items" VALUES(27,'genus','own','Genus Insight Lv10 (all genera)','',1,1.0,0.0,'per_server',1,1,0,'kr_tw_reference','provisional',26,'Insight levels to 10 with Insight Crystals (daily duties, passes). 9 rerollable effect slots (3 and 9 = attack). Titles for all genera at Lv10 and for all 200 pets. https://sagye.kr/tips/pets ; https://www.gametoc.co.kr/news/articleView.html?idxno=105439',NULL);
INSERT INTO "progression_items" VALUES(28,'titles','own','Unique titles','',1,12.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',27,'12 Unique titles (Monolith Lv30, Ereshkigal 20, all genera Lv10, 200 pets, 25 wings, 700 appearances, 300 PvP kills, sealed-dungeon sets, 6 episode chapters, +15 Unique gear). Owned stats always apply; equip 1 offensive, 1 defensive, 1 utility. Community owned-effect sum: PvE Atk +36, Acc +90, Def +130, dmg red. 3.5%, dmg amp 5%, HP +470. https://game8.co/games/Aion-2/archives/613096',NULL);
INSERT INTO "progression_items" VALUES(29,'wardrobe','own','Appearance collection','',1,700.0,0.0,'per_server',1,1,0,'kr_tw_reference','provisional',28,'Each appearance gives a small permanent stat (0.2% → 0.1% when made server-shared). 700 appearances → title (combat speed +5%, cooldown −5%). https://game.savetip.co.kr/aion-2-appearance-collection-guide-title/',NULL);
INSERT INTO "progression_items" VALUES(30,'wings','own','Wings collection','',10,25.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',29,'30+ wings (title counts 25). Equipped stats (e.g. Def Bonus 200, HP 300), owned Flight Power, +1..+10 enhance. Sources: quest ''The Power in the Lake'', morph 70 Featherdown + 10 Pure Odyle, Hidden Cubes, lvl-45 shops. Account sharing unconfirmed. https://game8.co/games/Aion-2/archives/614970',NULL);
INSERT INTO "progression_items" VALUES(31,'amulet_belt','own','Revelation Amulet (per grade)','',10,1.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',30,'10 enhance levels per grade then promote. Only Monolith scrolls upgrade it. Large Item Level gains (amount not found). https://www.gameple.co.kr/news/articleView.html?idxno=214553',NULL);
INSERT INTO "progression_items" VALUES(32,'amulet_belt','own','Noble Belt (per grade)','',10,1.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',31,'10 enhance levels per grade then promote. Only Stronghold scrolls upgrade it (enemy strongholds needed for Unique). Item Level amount not found. https://www.gameple.co.kr/news/articleView.html?idxno=214553',NULL);
INSERT INTO "progression_items" VALUES(33,'pantheon','own','Pantheon statues & paintings','',10,1.0,0.0,'per_character',1,1,1,'kr_tw_reference','unknown',32,'Personal hall; statues/paintings give permanent stats. Statue scraps from sealed dungeons; also Nightmare, field bosses, crafting. Amounts not found. https://www.rsnxt.com/News/aion-2-the-pantheon-system-your-guide-to-statues-art-and-power.html',NULL);
INSERT INTO "progression_items" VALUES(34,'arcana','own','Arcana slots (5)','',45,5.0,0.0,'per_character',1,1,1,'kr_tw_reference','provisional',33,'5 slots, cards up to +5, from Transcendence (repeatable farm). Biggest Item Level jump: grey 20, green 40, blue 60, gold 80 per card (value here = all 5 slots gold). On Global, Rare Arcana can drop from Transcendence 1. https://7mmo.com/threads/the-aion-2-bible-the-tryhard-guide-from-level-1-to-ludra.5351/',NULL);
